public interface Codec { String name(); }
// META-INF/services/com.example.Codec -> com.example.ZipCodec
public final class Codecs {
    private static final Map<String, Codec> REGISTRY =
        new ConcurrentHashMap<String, Codec>();
    static void discover() {
        for (Codec codec : ServiceLoader.load(Codec.class)) {
            REGISTRY.put(codec.name(), codec);
        }
    }
    public static Codec byName(String name) { return REGISTRY.get(name); }
}

