public final class ServiceRegistry {
    private final ConcurrentMap<String, Supplier<Service>> services =
        new ConcurrentHashMap<>();
    public void register(String key, Supplier<Service> supplier) {
        if (services.putIfAbsent(key, supplier) != null) {
            throw new IllegalStateException("duplicate: " + key);
        }
    }
    public Service lookup(String key) {
        Supplier<Service> s = services.get(key);
        if (s == null) throw new NoSuchElementException("unknown: " + key);
        return s.get();
    }
}
